pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (items are 10..80), so punish them hard beyond their raw value.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }

    // Reward exact fits and near-exact fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead space relative to bin capacity: penalize leaving large unusable
    // slack when item is small relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: make the empty bin moderately attractive only when
    // the current bin would leave bad dead space or when few bins fit.
    if bin_residual == bin_capacity {
        score = 55.0
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64) * 0.8
            - (item_size as f64 / bin_capacity as f64) * 20.0;
        // If this placement creates near-zero dead space elsewhere, discourage new bin.
        if post_residual <= 9 && post_residual >= 1 {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item can use the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 12.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be more willing to consolidate; later, tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable dead space penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Non-linear penalty on small-but-usable residuals that limit flexibility.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 12.0; // next item won't fit here; dead space likely
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    if bin_residual < bin_capacity {
        score += pressure * 0.3;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless it's a poor fit situation.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin if current bin would leave large dead space anyway.
        if post_residual > 40 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Exact fit: near-perfect bin.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    }

    // Lookahead: exact fit for next item is extremely valuable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            score -= 420.0;
        } else if pr >= nxt {
            let slack = (pr - nxt).min(30.0);
            let tight = 1.0 - (pr - nxt) / cap;
            score -= (140.0 - slack * 0.3) * (1.0 - prog2) * (0.8 + 0.4 * tight);
        } else {
            let gap = nxt - pr;
            let scarcity = if fitting_bins_count > 1 { 1.0 } else { 1.35 };
            score += gap * (1.1 + progress) * 0.55 * scarcity;
        }
    }

    // Tightness reward (squared), scaled by progress.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 5.0;

    // Fill ratio reward, scaled by progress (weakened to avoid overfitting).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0 * (0.5 + progress);

    // Consolidation pressure when many bins are open.
    score += (open_bins_count as f64) * 0.6;

    // Mean residual coupling (weakened).
    score -= (mean_residual - pr) * 0.1;

    // Last-chance bin: favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: open only when no good fit exists.
    if bin_residual == bin_capacity {
        score = 80.0
            - (fitting_bins_count as f64) * 12.0
            + (open_bins_count as f64) * 0.4
            - (item_size as f64 / bin_capacity as f64) * 30.0;
        if next_item_size > 0 && post_residual >= next_item_size as f64 {
            score -= 25.0;
        }
        if item_size >= bin_capacity / 2 {
            score -= 18.0;
        }
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let pr = post_residual as f64;

    // Exact fit: nearly perfect bin.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 9 {
        score += 25.0; // dead-space penalty
    }

    // Strong lookahead: exact fit for next item is extremely valuable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr == nxt {
            score -= 420.0;
        } else if pr >= nxt {
            let slack = (pr - nxt).min(30.0);
            score -= 160.0 * (1.0 - prog2) - slack * 0.25 * (1.0 - prog2);
        } else {
            score += (nxt - pr) * (1.1 + progress) * 0.55;
        }
    }

    // Fill ratio reward, scaled by progress.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0 * (0.5 + progress);

    // Consolidation pressure when many bins are open.
    score += (open_bins_count as f64) * 1.2;

    // Mean residual coupling.
    score -= (mean_residual - pr) * 0.25;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: open only when no good fit exists.
    if bin_residual == bin_capacity {
        score = 70.0
            - (fitting_bins_count as f64) * 8.0
            + (open_bins_count as f64) * 0.5
            - (item_size as f64 / bin_capacity as f64) * 25.0;
        // If item leaves a residue the next item can use, new bin is better.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Large items fill fresh bins well.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // Late in stream, prefer squeezing into existing bins.
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny residuals are nearly unusable.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Fill ratio reward.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: consolidate when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Strong lookahead: exact fit for next item is highly valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // New-bin candidate: attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score = 55.0
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64) * 0.8
            - (item_size as f64 / bin_capacity as f64) * 20.0;
        if post_residual >= 1 && post_residual <= 9 {
            score += 30.0;
        }
        // If next item is large and would waste this fresh bin, discourage.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer tighter bins relative to mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progress-scaled tightness bonus: later in stream, demand tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily
    if post_residual == 0 {
        score -= 1000.0;
    }
    if post_residual == next_item_size && next_item_size > 0 {
        score -= 500.0; // exact fit for the next item: ideal 2-step chain
    }

    // Lookahead: can the next item also fit into this bin afterwards?
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 30.0 + leftover_after_next as f64 * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit here; penalize small dead space that blocks it
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // Penalize post-residuals that are too small to be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when current bin fits poorly
    if bin_residual == bin_capacity {
        // neutral baseline relative to mean residual
        score = mean_residual.max(1.0) + 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = pr / cap; // 0..1 residual fraction after placement

    // Base: reward tight fits with a smooth non-linear decay.
    let mut score = 2.0 * (fit_ratio * fit_ratio) + 0.35 * fit_ratio;

    // Polynomial coupling of residual with stream progress:
    // early on, tolerate larger residuals (favor spreading); later, punish them harder.
    let coupling = (fit_ratio - 0.5) * (fit_ratio - 0.5) * (0.5 + 2.5 * progress);
    score += coupling * cap * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 1.5 + 2.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 0.6 + 0.8 * snug * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that wastes space relative to next item.
        score += 0.25 * (1.0 - progress) * (pr - next_item_size as f64) / cap;
    }

    // Mild penalty when many bins are open and this one is much above mean residual.
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: keep it slightly unattractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 0.4 + 1.2 * (1.0 - progress) * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally, but only if a decent chunk remains after
            let after_next = post_residual - next_item_size;
            score -= 15.0 * (after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for wasting capacity
            score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score += 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score -= 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: early in the stream, be conservative (favor filling existing
    // bins); late in the stream, allow more aggressive new-bin opening since
    // future flexibility matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is attractive only when the
    // item is large or the stream is late and many bins are already open.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let new_bin_bonus = 20.0 * large_item + 15.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
        score -= new_bin_bonus;
        // But if a good existing fit exists (many fitting bins), discourage new bin.
        if fitting_bins_count > 2 && post_residual == 0 {
            score += 10.0;
        }
    }

    // Perfect fit absolute reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

