pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: post_residual scaled by stream progress pressure.
    let pr = post_residual as f64;
    score += pr * pr * 0.02 * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * 10.0 * (0.5 + progress);

    // Penalize last-chance bins slightly unless fit is very tight.
    if fitting_bins_count == 1 {
        score += 5.0 * (1.0 - tightness);
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Mild penalty for many open bins with high mean residual (fragmentation).
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64 - 0.5).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly useless,
    // (10,20) can host the smallest items, etc. Reward larger usable classes.
    let cls = match post_residual {
        0 => 0.0,
        1..=9 => -60.0,          // tiny dead space: heavily penalize (add back)
        10..=19 => 25.0,
        20..=29 => 40.0,
        30..=49 => 55.0,
        50..=74 => 70.0,
        _ => 85.0,
    };
    score -= cls;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 100.0;
        } else if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.4;
        }
    }

    // New-bin candidate handling: empty bin has raw residual = capacity.
    // Only attractive when existing bins fit poorly (large dead space) or none fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        } else {
            // discourage opening new bin when decent fits exist;
            // scale with stream progress (waste compounds over long streams)
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 55.0 + 45.0 * progress;
            // but allow new bin if the best alternative residual is tiny dead space
            if post_residual > 0 && post_residual < 10 {
                score -= 70.0;
            }
        }
    }

    // Prefer filling bins with below-average residual (consolidate emptier bins).
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.3;
    }

    // Modulo-10 harmonic coupling: residual divisible by 10 aligns with the
    // item-size grid, making it reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer-division threshold: penalize leaving residual in awkward
    // half-class (5..15) that few items fit.
    if (5..15).contains(&post_residual) {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    // A residual that can never fit the minimum item (<= 1..10) is pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 25.0; // nearly dead: only tiny items can use it
    } else if post_residual <= 35 {
        score += 8.0;  // awkward zone
    } else if post_residual >= 50 {
        score -= 12.0; // large usable residual is valuable
    }

    // Perfect or near-perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: leftover space exactly matching next item is great;
    // leftover space just below next item is likely dead weight.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // confirmed dead space for the next item
        }
    }

    // Open-bins pressure: discourage scattering across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.5 + 2.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin becomes exactly sized for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual close to next item size: strong lookahead bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot fit in this bin afterwards: dead-space penalty scaled by tightness.
        let dead = (next_item_size - post_residual) as f64;
        score += 8.0 * (dead / bin_capacity as f64);
    }

    // Reward placing into bins whose residual is below the mean (tight bins first).
    score -= 5.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidate mildly so it only wins on truly bad fits,
    // but more attractively when many bins are open and mean residual is low.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Slight late-stream conservatism: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared dead-space penalty, amplified by fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score += (post_residual as f64) * (post_residual as f64) * 0.02 * (0.5 + fill);

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Slight preference to pack into crowded bins when alternatives exist.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward;
    // if post-residual is a "dead" sliver smaller than min item, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 6.0 + 0.1 * nx;
        } else if post_residual > 0 {
            score += 4.0; // creates dead space for the known next item
        }
        // Harmonic compatibility: post_residual close to next item is ideal.
        let gap = (post_residual as f64 - nx).abs();
        score -= 5.0 / (1.0 + gap);
    }

    // Dead-space trap: residual too small for the smallest possible item (1..100 unknown,
    // assume min 10) is wasted capacity -> penalize proportionally when bin is nearly full.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score -= fill * (open_bins_count as f64) * 1.5;

    // Global-state term: when mean residual is high, prefer bins above-average fullness.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - bin_res_f) * 0.15;
    }

    // Time horizon: early in stream, be pickier (penalize mediocre fits);
    // late in stream, accept placements to avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.05;
    score -= progress * 5.0;

    // New-bin candidate: only open a new bin if all open bins are nearly full
    // or the item is huge with poor fits elsewhere.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let desperation = (avg_fullness * 40.0) + (fill * 20.0);
        let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
        score = 60.0 + (fitting_bins_count as f64) * 10.0 - desperation - open_pressure;
        if fitting_bins_count == 0 {
            score = -100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: early stream favors tight fits,
    // late stream penalizes wasted residual more strongly
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward near-perfect fits with a smooth quadratic bonus
    let fit_quality = 1.0 - norm_pr;
    score -= (1.0 - fit_quality * fit_quality) * 20.0;

    // Dead-space penalty: residual too small to fit typical future items
    let dead_zone = (15.0_f64 - pr).max(0.0) / 15.0;
    score += dead_zone * dead_zone * 25.0 * (0.5 + progress);

    // Lookahead: smooth reward if next item fits the post-residual
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += (-gap / cap) * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    score += 0.05 * open_bins_count as f64 * norm_pr * norm_pr;

    // New-bin candidate calibration: keep it competitive only for large items
    if bin_residual == bin_capacity {
        score = pr + 12.0 * (1.0 - item_size as f64 / cap) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity used by this placement
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward high fill ratios (tight packing)
    score -= 40.0 * fill * fill;

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    // Leftovers that cannot accommodate a "typical" small item are dead space.
    let small = 10u32.min(bin_capacity / 4).max(1);
    let mid = bin_capacity / 3;
    if post_residual > 0 && post_residual < small {
        // dead space: unusable sliver -> strong penalty scaled by how much was wasted
        score += 25.0 + 0.5 * (small - post_residual) as f64;
    } else if post_residual == 0 {
        // perfect closure: strongly reward exact bin completion
        score -= 60.0;
    } else if post_residual <= mid {
        // leftover in the "awkward middle band": mildly penalize
        score += 8.0;
    } else {
        // generous leftover: reward flexibility, more so if it can hold next item
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly into the post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next fits, but measure the resulting slack quality
            let slack = post_residual - next_item_size;
            if slack < small {
                score += 12.0; // would create a future dead sliver
            } else {
                score -= 8.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // next item will NOT fit here: if this is the only fitting bin, we must
            // consider whether closing this bin now is fine
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (item leaves a large, awkward leftover) or few bins fit the item.
        let leftover_bad = (bin_residual - item_size) < small;
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        // base cost of consuming a fresh bin
        score += 45.0;
        if leftover_bad { score -= 20.0; }
        score -= 25.0 * scarcity;
        // early in the stream, new bins are cheap (plenty of stream left to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean residual (tighter bins first),
    // keeping looser bins available for larger future items.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild pressure against hoarding many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold the smallest
    // future item are pure waste — penalize them hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Reward extremely tight fits (post_residual small but usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space relative to bin capacity: penalize leaving gaps that are
    // too small for typical items (1..100 range => gaps < 1 are waste,
    // gaps < 10 are near-waste).
    let dead_ratio = (bin_capacity - post_residual.min(bin_capacity)) as f64 / bin_capacity as f64;
    score += 10.0 * dead_ratio * dead_ratio;

    // Open-bin pressure: discourage spreading items across many bins unless
    // the fit is genuinely good; a new empty bin is penalized so we prefer
    // reusing bins with decent fits.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: only attractive when current bins are
        // congested or the fit elsewhere would be terrible.
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    } else {
        // Existing-bin usage gets a mild bonus scaled by how many bins fit.
        if fitting_bins_count == 1 {
            score -= 20.0; // last-chance bin: use it before opening new
        }
        score -= 1.0 * (mean_residual - post_residual as f64).abs().min(10.0);
    }

    // Lookahead coupling: if the next item would fit perfectly into the
    // post-residual, reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 20.0; // blocks next item with unusable gap
        }
    }

    // Late in the stream, consolidate aggressively to avoid opening bins
    // that will never be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the new residual -> huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward tight leftover after the pair.
            let pair_left = post_residual - next_item_size;
            score -= 0.5 * (next_item_size as f64) - 0.8 * (pair_left as f64);
            if pair_left == 0 {
                score -= 500.0;
            }
        } else {
            // Next item cannot use this bin's residual: penalize proportionally.
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize dead space relative to mean residual (avoid leaving unusable gaps).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 50.0; // tiny useless sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bins would waste badly.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        score = waste_if_open + 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        }
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
    }

    // Slight preference for tighter bins overall as stream progresses.
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: square the post-residual penalty (dead space is superlinear bad).
    score += (post * post) / (2.0 * cap);

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_after_next = post - nxt;
            score -= 12.0 * (1.0 - slack_after_next / cap);
        } else {
            // Next item won't fit here; slightly penalize leaving awkward residual.
            score += 2.0 * (post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, reward using it heavily
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins with residual far below mean are scarce space,
    // prefer filling them; bins with residual above mean are roomy, mild penalty.
    let res = bin_residual as f64;
    let dev = (res - mean_residual) / cap;
    score += 5.0 * dev;

    // Time horizon: late in the stream, avoid opening new bins (waste grows),
    // early in the stream, allow exploration of fresh bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 8.0 + 25.0 * progress;
        // But if item is huge relative to typical residual, new bin is fine.
        score -= 6.0 * (item_size as f64 / cap);
    } else {
        // Using an existing bin late in the stream is extra good.
        score -= 3.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64;

    // Small bonus for using bins that would otherwise be nearly dead.
    if post < 10.0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: penalize wasted space with a non-linear (quadratic) term.
    let mut score = post * post / cap;

    // Smooth coupling: waste matters more as the stream progresses.
    score += 0.35 * progress * post;

    // Cubic decay of residual utility: small residuals are nearly worthless dead space.
    score -= 0.15 * (1.0 - (post / cap).powi(3)) * item;

    // Reward tight fits via smooth sigmoid-like term of fill ratio.
    let fill = item / cap;
    score -= 8.0 * (fill * std::f64::consts::PI).sin().abs();

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual (smooth margin term).
    if nxt > 0.0 {
        let margin = (post - nxt) / cap;
        if margin >= 0.0 {
            score -= 2.0 * (1.0 - margin.abs());
        } else {
            score += 1.5 * margin.abs();
        }
    }

    // Penalize bins far from the mean residual (avoid fragmentation outliers).
    score += 0.05 * (post - mean_residual).abs();

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10
    let class = (post_residual % 10) as f64;
    score += class * 0.15; // prefer leftovers that are "round" (class 0 = most reusable)

    // Dead-space penalty: tiny leftovers that almost nothing fits into
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // worst: fragment wasted
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: reward if the next item can fit into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 + 0.3 * tight;
        } else {
            // next item cannot use this leftover: penalize proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.2 * gap;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive unless
    // item fits very poorly everywhere else. Penalize proportional to open bins wasted.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // but if the item is huge relative to typical residual, allow opening
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Favor fuller bins: subtract for how much of capacity was consumed
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
        // tie-break toward bins whose residual is close to mean (keep balance)
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Stream progression: late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Integer-division threshold bonus on post_residual (harmonic classes of 25)
    match post_residual / 25 {
        0 => score += 5.0,          // 0..24: poor leftover
        1 => score -= 2.0,          // 25..49: decent
        2 => score -= 4.0,          // 50..74: good
        _ => score -= 1.0,          // 75..99: large but not perfect
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1) are always wasted, but residuals too small
    // for any "likely" item are far more damaging. Penalize the dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap = worst outcome
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Penalize gaps that cannot fit the lookahead item if this bin is
    // otherwise a candidate for it (wasted pairing opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward reserving space for the next item when it fits exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.15;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // a good fit exists; encourage using existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin should only win when
    // existing fits are poor. Give it a mild penalty by default so it
    // loses to decent fits, but its raw post_residual (= capacity - item)
    // is large, which already works against it for large items.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is large relative to capacity, opening a fresh
        // bin is often correct (avoid fragmenting a partially-filled bin).
        if (item_size as f64) > 0.6 * (bin_capacity as f64) {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: when open bins are on average spacious,
    // prefer consolidating into the tightest fit; when bins are tight,
    // be more tolerant of moderate post_residual.
    let tightness = mean_residual / bin_capacity as f64;
    score -= tightness * 6.0;

    // Late in the stream, be slightly more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little slack left after it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }
    // Penalize blocking the next item (post_residual too small for it but nonzero).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Reward tight fits generally.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual across open bins: prefer bins that are tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New empty bin candidate: penalize it unless it's the only option.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // Late in the stream, consolidate into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size (1..=small) is worthless.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 30.0;

    // Penalize creating residual that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 15.0 + (post_residual - next_item_size) as f64 * -0.3;
        } else {
            // next item won't fit here; slight penalty for large leftovers
            score += (post_residual as f64 - (next_item_size as f64)).max(0.0) * 0.1;
        }
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // this bin's fit is poor or the item is huge.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // more attractive when few bins are open (early stream) or
        // when the item is large relative to capacity
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // if many bins are open with plenty of residual, discourage new bin
        score += (open_bins_count as f64).ln().max(0.0) * 6.0;
        score += (mean_residual / bin_capacity as f64) * 25.0;
    } else {
        // existing bin: prefer bins with larger residual consumed proportionally
        score += (bin_residual as f64 - item_size as f64) * 0.05;
        // prefer bins whose residual is close to item (best fit)
        score -= (bin_capacity as f64) / ((bin_residual - item_size + 1) as f64) * 0.5;
    }

    // Mild time-horizon coupling: late in the stream, consolidation matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (fitting_bins_count as f64).recip().max(0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth non-linear base: quadratic reward for tight fits
    let mut score = pr * (1.0 + 0.8 * fill * fill);

    // Cubic coupling of fill with stream progress: prefer tight fits later
    score -= 12.0 * fill * fill * fill * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * fill;
    }

    // Lookahead: reward leaving space for the next item (smooth kernel)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 6.0 * (-slack / cap).exp();
    }

    // Mild penalty for spreading across many open bins when residual is large
    score += 0.02 * open_bins_count as f64 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction of the filled portion
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class of post_residual: mod-10 buckets penalize awkward dead space
    let pr_mod = post_residual % 10;
    let dead_penalty = match pr_mod {
        0 => -30.0,                    // perfectly flush: excellent
        1..=4 => 2.0 * pr_mod as f64,  // small slivers: mildly bad
        5..=9 => (9 - pr_mod as f64),  // larger leftover: ok-ish
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division thresholds: post_residual in [50..] means bin half-empty -> waste
    let half = bin_capacity / 2;
    if post_residual > half {
        score += 8.0 * (post_residual - half) as f64 / half as f64;
    } else if post_residual <= 10 {
        score -= 15.0; // nearly closed bin, great
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely; reward especially if combined fill is harmonic
            let combined = item_size + next_item_size;
            if combined % 10 == 0 {
                score -= 25.0; // pair sums to full decade: harmonic class match
            } else {
                score -= 6.0;
            }
            score -= 3.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if post_residual is a dead zone
            if post_residual < 10 {
                score += 5.0; // unavoidable sliver, mild
            } else {
                score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size
    // (residual == capacity). Prefer new bins only when current bin fit is poor.
    if bin_residual == bin_capacity {
        // penalize opening a new bin unless it gives a very tight fit
        let tight = item_size as f64 / bin_capacity as f64;
        if tight < 0.5 {
            score += 30.0; // discourage opening bins for small items
        } else {
            score += 5.0 * (1.0 - tight); // mild penalty, tight fits compete
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0; // new bin will likely chain with next item
        }
    }

    // Stream progression: early on, be conservative with bin count
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > mean_residual.max(1.0) {
        score += 1.0;
    }
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: heavy penalty, worse the smaller the gap.
            score += (11.0 - post_residual as f64) * 12.0;
        } else if post_residual < 20 {
            score += (20.0 - post_residual as f64) * 2.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits generally (high fill ratio).
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += pressure * 2.0;
        // But if it enables a great fit for the next item, soften slightly.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (next_item_size as f64 / 10.0);
        }
    } else {
        // Reward using existing bins, scaled by pressure.
        score -= pressure * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mildly penalize creating stranded space.
        score += 3.0;
    }

    // Prefer bins below the mean residual (keep residuals balanced, avoid outliers).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: eliminate the bin entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward residuals that exactly host the next item,
    // and reward residuals that can host the next item at all.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // chain of two perfect fits
        } else if post_residual >= next_item_size {
            score -= 30.0;  // next item still fits here
        } else {
            // dead space too small for the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // bonus if post_residual can host next item AND we're near the end of the stream
        if post_residual >= next_item_size && total_items > 0 && step_index as f64 / total_items as f64 > 0.8 {
            score -= 20.0;
        }
    }

    // Penalize small unusable dead space (items are >= 1, but small gaps are wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are poor. Make the empty-bin candidate moderately attractive
    // so bad placements (large dead space) are avoided, but not when a good fit exists.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 5.0;
        if next_item_size > 0 && item_size == next_item_size {
            score -= 10.0; // pairing identical items in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits anywhere: new bin mandatory
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += mean_residual * 0.05 - open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress) - 1.2 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual), more so later in the stream
    let mut score = pr - 6.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space that is too small to be useful, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).max(0.0) / cap;
        score -= 4.0 * usable * (1.0 + poly.abs());
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual across bins
    score += 0.3 * (bin_residual as f64 - mean_residual).abs() / cap;

    // Slight bias toward fewer open bins early, consolidation later
    score += 0.05 * open_bins_count as f64 * progress;

    score + 2.0 * poly
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Reward small post_residual with extra weight on fine-grained classes
    let class = (frac * 8.0).floor() as i32; // 0..=8 harmonic octave
    score -= (8 - class) as f64 * 1.5;

    // Perfect fit bonus: post_residual in {0, small remainders} via modulo classes
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // residual aligned to decimal harmonic classes -> likely reusable
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Penalize awkward dead space: post_residual in (5..15) rarely reusable for items >=10
    if post_residual > 5 && post_residual < 15 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
        // Harmonic divisibility: next item divides remaining space evenly
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // must open new bin
        } else {
            // opening a new bin wastes existing residual; penalize relative to mean residual
            score += 20.0 + mean_residual * 0.5;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.1;

    // Tie-break: prefer bins whose residual is close to item (tight fit)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Many open bins: encourage filling existing ones over spreading
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    }
    // Near match: next item fits with little slack left after it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Sharper reward when the leftover after next item is small or reusable.
        if slack <= (bin_capacity as f64 * 0.1) {
            score -= 40.0;
        } else {
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        }
    }
    // Penalize blocking the next item (post_residual too small for it but nonzero).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Stronger penalty when the blocked slack is large enough to have held next item
        // in a different bin; scale by how close it was to fitting.
        let miss = (next_item_size - post_residual) as f64;
        score += 20.0 + 15.0 * (1.0 - miss / bin_capacity as f64);
    }

    // Reward tight fits generally.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count == 2 {
        // With two candidates, mildly encourage consolidation onto the tighter one.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New empty bin candidate: penalize it unless the item is large relative to
    // remaining capacity structure (big items are better isolated early).
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score += 15.0; // big items: new bin less penalized
        } else {
            score += 40.0;
        }
    }

    // Late in the stream, consolidate into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 14.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Coupling: when many open bins exist, prefer filling the tightest ones to
    // close them out; when few are open, keep some spread to preserve options.
    if open_bins_count > 8 {
        score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    }
    // Near match: next item fits with little slack left after it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }
    // Penalize blocking the next item (post_residual too small for it but nonzero).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Worse if the blocked slack is small (wasted space).
        let waste = post_residual as f64 / next_item_size.max(1) as f64;
        score += 15.0 + 25.0 * (1.0 - waste);
    }

    // Reward tight fits generally, scaled by item size (big items deserve tight fits more).
    let size_frac = item_size as f64 / bin_capacity as f64;
    score -= (10.0 + 15.0 * size_frac) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual across open bins: prefer bins that are tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Two-step lookahead: if after placing next item the residual would be zero, bonus.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 2 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count == 2 {
        score -= 15.0;
    }

    // New empty bin candidate: penalize unless the next item is large and no open bin
    // could hold both item and next item (avoid fragmenting future capacity).
    if bin_residual == bin_capacity {
        let next_big = next_item_size as f64 > 0.5 * bin_capacity as f64;
        let scarce = fitting_bins_count <= 1;
        if next_big && !scarce {
            score += 10.0; // gentler penalty: fresh bin may serve big next item
        } else {
            score += 40.0;
        }
    }

    // Late in the stream, consolidate into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is an exact multiple-friendly value for small items.
    if post_residual > 0 && post_residual <= 20 && item_size <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect 2-step lookahead match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 65.0;
    }
    // Near match: next item fits, reward tightness of the remaining slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 28.0 * (1.0 - slack / cap);
        // Extra reward when the slack after next item is small enough to be useful
        // but not so large that we wasted space.
        if slack > 0.0 && slack < 0.15 * cap {
            score -= 12.0;
        }
    }
    // Penalize blocking the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Scale penalty by how badly we block: closer to next size = less bad.
        let miss = (next_item_size - post_residual) as f64;
        score += 18.0 + 20.0 * (1.0 - (miss / next_item_size.max(1) as f64).min(1.0));
    }

    // Reward tight fits, mildly amplified.
    score -= 18.0 * (1.0 - post / cap);

    // Compare against mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - post) * 0.35;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New empty bin candidate: penalize normally, but if the item is large
    // relative to capacity AND no open bin gives a tight fit, opening a new
    // bin preserves large residuals elsewhere for future items.
