pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }
    // Medium gaps (11..25) are moderately wasteful too.
    if post_residual > 10 && post_residual <= 25 {
        score += (post_residual as f64 - 10.0) * 1.5;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Reward when this residual could still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: dead space penalty.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let bad_open_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 15.0 };
        score += 20.0 + open_bins_count as f64 * 5.0 - bad_open_fit;
