fn score_bin_impl (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let post = post_residual as f64 ;
    let fill_ratio = 1.0 - post / cap ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;

    // Exact lookahead fit: strong reward, amplified when few alternatives
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 72.0 ;
        if fitting_bins_count <= 2 { score -= 8.0 ; }
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        let norm = slack / cap ;
        score -= 32.0 * (1.0 - norm) * (1.0 - 0.5 * norm) ;
        // tight-but-usable leftover after next item is ideal
        if slack < 8.0 { score -= 7.0 ; }
        else if slack > cap * 0.5 { score += 4.0 ; }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 26.0 ;
        // worse late in stream: dead space can never be recovered
        score += 10.0 * progress ;
    }

    // base fill reward, slightly stronger
    score -= 18.0 * fill_ratio ;
    score -= (mean_residual - post) * 0.35 ;

    // progress-weighted compaction pressure
    score -= progress * 16.0 * fill_ratio ;

    // scarcity of alternatives
    if fitting_bins_count > 0 {
        score -= 8.0 * (1.0 - 1.0 / fitting_bins_count as f64) * fill_ratio ;
    }

    // dead-space shaping: penalize residuals too small for typical items,
    // scaled by remaining stream length
    if post > 0.0 && post < 10.0 {
        score += 4.0 + 4.0 * (1.0 - progress) ;
    }

    // new-bin candidate: penalize unless open bins are truly bad or the
    // next item would waste most of a fresh bin anyway
    if bin_residual == bin_capacity {
        let waste_estimate = if next_item_size > 0 { (cap - next_item_size as f64).max (0.0) } else { 0.0 } ;
        let mut penalty = 7.0 + 0.07 * waste_estimate - 4.0 * progress ;
        // if current bin residual barely fits item, new bin looks better
        if bin_residual >= item_size && bin_residual - item_size < 4 {
            penalty -= 5.0 ;
        }
        score += penalty ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack remaining after also fitting next item: mildly penalize waste.
            let leftover = post_residual - next_item_size;
            score -= 50.0 - (leftover as f64).min(50.0);
        } else if post_residual > 0 {
            // Dead space that cannot host the lookahead item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 30.0 + dead * 0.8;
        }
    }

    // Penalize tiny unusable residuals (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, encourage consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // Brand-new empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual > 0
            && post_residual < next_item_size
            && post_residual < 10;
        if poor_fit {
            score -= 20.0; // allow opening new bin on truly bad fit
        } else {
            score += 120.0; // otherwise prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 0.35 * bin_capacity as f64;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 18.0 + 12.0 * (1.0 - chain_quality / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't chain here; penalize proportionally to how close it was.
        let gap = (next_item_size as f64 - post_residual as f64).min(30.0);
        score += gap * 0.6;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; prefer best-fit among them.
        score += 4.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer filling bins with larger residuals when overall residuals are high (fragmentation control).
    let res_gap = mean_residual - bin_residual as f64;
    score += res_gap * 0.25;

    // Time horizon: late in the stream, avoid opening new bins; consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 30.0 + 60.0 * progress;
        // Allow a new bin early or when the item is large and nothing fits well.
        if item_size > 60 && tightness < 0.45 {
            score -= 25.0 * (1.0 - progress);
        }
    } else {
        // Existing bin: increasingly rewarded late in the stream.
        score -= 15.0 * progress;
    }

    // Mild preference for bins that are already well loaded (larger item_size used).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Coupling: many open bins -> encourage consolidation into loaded bins.
    score += (open_bins_count as f64).ln().max(0.0) * (tightness * 10.0);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
