    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual (tight packing), scaled by progress.
    let mut score = post * (0.5 + progress);

    // Smooth polynomial coupling: reward tight fits (small post_residual) with a
    // non-linear term that peaks when the bin is nearly full.
    let fill_ratio = 1.0 - post / cap;
    score -= 30.0 * fill_ratio * fill_ratio * (0.3 + 0.7 * progress);

    // Penalize dead space that is too small to be useful for future items,
    // with a smooth quadratic penalty around the "unusable" region.
    let dead_zone = (cap * 0.2 - post).max(0.0) / (cap * 0.2);
    score += 20.0 * dead_zone * dead_zone * (1.0 - progress);

    // Last-chance bonus: strongly favor using a bin when few can fit the item,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count <= 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // Mild penalty for consuming scarce fitting bins when alternatives exist.
        score += (fitting_bins_count as f64).ln() * (2.0 * (1.0 - progress));
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let match_closeness = 1.0 - (post - nxt) / cap;
            score -= 18.0 * match_closeness * match_closeness;
        } else {
            // Penalize leaving residual too small for the known next item.
            score += 6.0 * (1.0 - progress);
        }
    }

    // Encourage balancing residuals across bins: penalize deviation from mean residual.
    let dev = (post - mean_residual).abs() / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // New-bin candidate handling: an empty bin should only win if open bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; slight progress-dependent cost of adding bins.
        score += 8.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 12.0; // fresh bin reserves room for lookahead item
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 ;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size ;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64) ;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 + 0.15 * (next_item_size - post_residual) as f64 ;
    }
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    score -= (mean_residual - post_residual as f64) * 0.3 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    // Penalize new empty bins more when several open bins already fit the item
    if bin_residual == bin_capacity {
        let crowding = if fitting_bins_count > 1 { fitting_bins_count as f64 } else { 1.0 } ;
        score += 18.0 + 6.0 * (crowding - 1.0) . min (3.0) ;
        // allow a fresh bin only when the item is large relative to capacity
        score -= 10.0 * (item_size as f64 / bin_capacity as f64) ;
    }
    // mild bonus for bins that remain versatile after placement
    if post_residual > 0 && next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 4.0 ;
    }
    // discourage leaving tiny unusable fragments
    if post_residual > 0 && post_residual < 8 {
        score += 12.0 ;
    }
    score
