pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: tiny dead space (<10) is nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo classes on post_residual (capacity fractions / divisibility bands).
    let pr = post_residual;
    if pr % 50 == 0 && pr > 0 {
        score -= 30.0; // half-capacity residual is highly reusable
    } else if pr % 25 == 0 && pr > 0 {
        score -= 15.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    } else {
        // Non-aligned residuals: penalize by distance to nearest multiple of 10.
        let dist = (pr % 10).min(10 - pr % 10) as f64;
        score += dist * 1.5;
    }

    // Integer-division threshold on post_residual: big residuals are flexible.
    if pr / 25 >= 2 {
        score -= 12.0;
    } else if pr / 25 == 1 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            // next item fits: scale reward by how well it fills
            let fill = next_item_size as f64 / pr as f64;
            score -= 60.0 * fill;
            if pr - next_item_size < 10 {
                score -= 25.0; // chain of tight fits
            }
        } else {
            // next item cannot use this residual: mild penalty, stronger if residual tiny
            score += 5.0 + (10.0 - (pr as f64).min(10.0)) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        // Penalize opening a new bin; penalty shrinks if open bins are crowded.
        score += 90.0 + 20.0 * pressure;
        if mean_residual < item_size as f64 * 1.2 && fitting_bins_count == 0 {
            score -= 150.0; // nothing fits anywhere: open a bin
        }
        // Late in stream, avoid leaving many nearly-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean (best-fit flavor), scaled by spread.
    let diff = mean_residual - bin_residual as f64;
    score += diff.clamp(-50.0, 50.0) * 0.6;

    // Mild preference to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

