    score -= 16.0 * fill_ratio ;
    score -= (mean_residual - post) * 0.3 ;

    // progress-weighted compaction pressure
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 14.0 * fill_ratio ;

    // scarcity of alternatives
    if fitting_bins_count > 0 {
        score -= 7.0 * (1.0 - 1.0 / fitting_bins_count as f64) * fill_ratio ;
    }

    // dead-space shaping: penalize residuals too small for typical items,
    // but scale with progress (early dead space can still be filled)
    if post > 0.0 && post < 10.0 { score += 5.0 * (0.5 + 0.5 * progress) ; }

    // NEW: prefer bins whose residual is a near-exact multiple of common item bands
    if post >= 1.0 && post <= 25.0 { score += 2.0 * (1.0 - post / 25.0) ; }

    // new-bin candidate: penalize more strongly unless open bins are truly bad
    if bin_residual == bin_capacity {
        let waste_estimate = if next_item_size > 0 { (cap - next_item_size as f64).max (0.0) } else { 0.0 } ;
        // NEW: open a new bin more readily when few bins fit and mean residual is low
        let scarcity = if fitting_bins_count <= 1 { 4.0 } else { 0.0 } ;
        score += 6.0 + 0.06 * waste_estimate - 3.0 * progress - scarcity
            - (mean_residual / cap) * 5.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: tiny leftover gaps that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium penalty for gaps below the minimum plausible item size range (1..100 stream,
    // but small gaps < 15 are statistically hard to fill).
    else if post_residual < 15 {
        score += 12.0 * (15.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: only one open bin can fit this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: mildly discourage spreading across many bins,
    // but only for small-to-medium items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_penalty = open_bins_count as f64 * (1.0 - progress) * 0.6;
    score += spread_penalty * (1.0 - item_size as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a fresh bin is only attractive for large items
    // or when the current bin would leave a badly fragmented residual.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 20.0 * (frac - 0.5); // large items: new bin is fine
        } else {
            score += 18.0 * (0.5 - frac); // small items: strongly prefer existing bins
        }
        // If no open bin fits (fitting_bins_count refers to open bins), new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Lookahead: if the next item would fit exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10 {
        score += 8.0; // next item would create dead space here
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let post = post_residual as f64 ;
    let fill_ratio = 1.0 - post / cap ;
    let next = next_item_size as f64 ;

    // Exact lookahead fit: strong reward
    if next_item_size > 0 && post_residual == next_item_size { score -= 75.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        let norm = slack / cap ;
        score -= 32.0 * (1.0 - norm) * (1.0 - 0.5 * norm) ;
        if slack < 8.0 { score -= 6.0 ; }
        // reward slack that still fits a typical small item
        if slack >= 20.0 && slack < 45.0 { score -= 2.5 ; }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 26.0 ;
