pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0 * (10.0 - post_residual as f64);
    } else if post_residual < 15 {
        score += 10.0 * (15.0 - post_residual as f64);
    }

    // Strong lookahead: exact fit for the next item is highly valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        // Reward placements where the next item still fits snugly.
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement strands the next item here; penalize.
        score += 20.0;
    }

    // Reward near-perfect fits.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: only one open bin can fit this item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Normalize fill quality: prefer bins that end up full.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Best-fit flavor: compare against mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progress-aware pressure: later in the stream, pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 20.0 * (frac - 0.5);
        } else {
            score += 18.0 * (0.5 - frac);
        }
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual large enough for next item: good, reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * (post_residual as f64 - next_item_size as f64).min(20.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item: penalize dead space harder.
        score += 10.0 + 0.25 * post_residual as f64;
    }

    // Penalize very small unusable slivers (dead space), but exact zero residual is perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 40.0;
    }

    // Compare against mean residual: bins with residual well below mean are "tight",
    // prefer filling them; bins above mean are roomy, slight penalty.
    score -= 0.20 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no tight fit exists elsewhere;
    // make empty-bin baseline moderately high so it loses unless open bins are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item exactly fills a fresh bin after this one (item + next == capacity),
        // opening a new bin is attractive.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 50.0;
        }
        // Late in the stream with many open bins, prefer consolidating instead.
        if total_items > 0 && step_index as f64 / total_items as f64 > 0.85 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let post = post_residual as f64 ;
    let fill_ratio = 1.0 - post / cap ;
