    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        let norm = slack / cap ;
        score -= 34.0 * (1.0 - norm) * (1.0 - 0.5 * norm) ;
        if slack < 8.0 { score -= 7.0 ; }
        if slack >= 20.0 && slack < 45.0 { score -= 3.0 ; }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 28.0 ;
    }

    // two-step lookahead: reward residuals that fit next item AND leave room for a small follow-up
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack2 = post_residual - next_item_size ;
        if slack2 >= 1 && slack2 <= 12 { score -= 4.0 ; }
    }

    // base fill reward, slightly stronger
    score -= 19.0 * fill_ratio ;
    score -= (mean_residual - post) * 0.38 ;

    // progress-weighted compaction pressure
    score -= progress * 17.0 * fill_ratio ;

    // scarcity of alternatives
    if fitting_bins_count > 0 {
        score -= 9.0 * (1.0 - 1.0 / fitting_bins_count as f64) * fill_ratio ;
    }

    // dead-space shaping: penalize residuals too small for typical items
    if post > 0.0 && post < 10.0 { score += 6.5 ; }
    if post > 0.0 && post < 5.0 { score += 4.0 ; }

    // new-bin candidate: penalize more strongly unless open bins are truly bad
    if bin_residual == bin_capacity {
        let waste_estimate = if next_item_size > 0 { (cap - next).max (0.0) } else { 0.0 } ;
        score += 7.5 + 0.08 * waste_estimate - 4.0 * progress ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid near-zero slivers
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, 1 = perfect fit

    // Perfect-ish fits get strong reward
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: prefer using existing bins unless fit is poor
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it becomes attractive only
        // if existing bins would leave large wasted residual.
        score += 15.0;
        // Early in stream, opening bins is cheaper (more flexibility later)
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * (1.0 - progress);
        // If many open bins already, discourage spreading
        score += 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can slot in: excellent packing chain
            score -= 12.0;
            // Extra reward for exact chain fit
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap
            let gap_waste = post as f64 - (post % next_item_size as f64);
            score += 0.3 * gap_waste;
        }
    }

    // Global state coupling: if mean residual is high, bins are loose;
    // prefer filling the tightest bin (large item_size relative to mean residual)
    let tightness = item_size as f64 / (mean_residual + 1.0);
    score -= 8.0 * tightness.min(1.0);

    // Time horizon: late in stream, minimize waste aggressively
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.5 * progress * (post / cap);

    // Mild penalty for very small post residuals that are not exact fits
    if post_residual > 0 && post_residual <= 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // As stream progresses, penalize wasted residual more aggressively (smooth ramp)
    score += 6.0 * prn * prn * (0.5 + p2) * cap * 0.1;
    score -= 2.0 * prn * (1.0 - p3);

    // Dead-space term: cubic in normalized residual, weighted by progress
    score += 3.0 * prn * prn * prn * (1.0 + 2.0 * p2);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - prn) * (1.0 - prn) * (2.0 + 4.0 * progress);

    // Lookahead: if next item fits exactly into post_residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let tight = 1.0 - ((pr - nxt) / cap);
            score -= 5.0 * tight * tight * (1.0 + progress);
        } else {
            // post_residual too small for next item: penalize if it becomes dead space
            score += 2.0 * prn * (0.5 + p2);
        }
    }

    // Last-chance bonus: unique fitting bin should be strongly favored
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * (1.0 - prn) * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (prefer balance)
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * (1.0 + p2);

    // New-bin candidate: smooth discouragement early, allowed late if residuals are poor
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        score += 8.0 * (1.0 - progress) + 4.0 * (1.0 - mean_frac) * (1.0 - mean_frac);
        score -= 3.0 * p3 * mean_frac;
    }

    // Slight penalty for opening/using many bins simultaneously
    score += 0.05 * open_bins_count as f64 * (0.5 + p2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact lookahead match
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward tight-but-fitting lookahead
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }
    // Penalize dead space that blocks the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Base compaction pressure
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    score -= (mean_residual - post_residual as f64) * 0.3;

    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // NEW-BIN CANDIDATE handling: empty bin must be penalized so it only wins
    // when no open bin fits, or when the leftover would be dead space anyway.
    if bin_residual == bin_capacity {
        let mut penalty = 120.0;
        // Late in the stream, or when few bins fit, opening fresh is more acceptable
        penalty -= progress * 40.0;
        if fitting_bins_count == 0 {
            penalty -= 200.0; // no alternative: allow new bin
        } else if fitting_bins_count == 1 && next_item_size > 0 && post_residual >= next_item_size {
            // an open bin fits and can still host the next item: strongly prefer it
            penalty += 30.0;
        }
        // If mean residual across bins is small, bins are nearly full; a new bin
        // is a natural continuation rather than fragmentation.
        if mean_residual < bin_capacity as f64 * 0.15 {
            penalty -= 25.0;
        }
        score += penalty;
    }

    // Mild penalty for leaving residuals just below common small-item sizes
    if post_residual > 0 && post_residual < 12 {
        score += 6.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
