    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        score -= 30.0 * (1.0 - slack / cap) ;
    }
    // dead-space penalty when item leaves unusable gap
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 ;
    }

    score -= 18.0 * fill_ratio ;
    score -= (mean_residual - post) * 0.35 ;

    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 12.0 * fill_ratio ;

    // scarcity pressure: fewer fitting bins -> value this bin more
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 8.0 ;
    }

    // discourage opening a new bin unless it is genuinely tight
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - item_size as f64 / cap) ;
    }

    // reward near-perfect compaction
    if post_residual > 0 && post_residual <= 3 {
        score -= 12.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (<= 10 or in a dead zone like 51..=60) are bad.
    let pr = post_residual;
    let dead_zone = (51..=60).contains(&pr) || (71..=80).contains(&pr);
    if dead_zone {
        score += 12.0;
    }

    // Reward near-perfect fits using integer division thresholds.
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 18.0;
    } else if pr <= 10 {
        score -= 8.0;
    }

    // Modulo arithmetic on capacity fractions: leftover congruent to small
    // classes mod 25 pairs well with tiny future items.
    let frac = (pr % 25) as f64;
    score -= 0.3 * (10.0 - frac).max(0.0);

    // Lookahead coupling: if next item can exactly use the leftover, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr && (pr - next_item_size) <= 10 {
            score -= 10.0;
        } else if next_item_size > pr {
            // leftover too small for next item: penalize proportionally
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: baseline penalty so it is only chosen when it beats
    // genuinely bad fits; relax late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
        // prefer new bin if mean residual across open bins is tiny
        score -= (cap - mean_residual).max(0.0) * 0.05;
    }

    // Mild preference for tighter bins relative to the fleet mean residual.
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Penalize very loose fills early (waste large space when stream is long).
    if progress < 0.5 && item_size < 40 && bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
