        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64) ;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 22.0 ;
    }
    // penalize dead space more sharply when few fitting bins remain (risk of stranding)
    if fitting_bins_count <= 1 {
        score += 18.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    }
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    score -= (mean_residual - post_residual as f64) * 0.3 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    // discourage opening a new bin when open bins still offer a decent fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        let best_open = mean_residual . max (0.0) ;
        if best_open >= item_size as f64 {
            score += 12.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: gaps too small for typical items are wasted.
    // Treat gaps < 10 as near-dead (hard to fill), gaps in [10, 30) as semi-dead.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 30 {
            score += 25.0 * (1.0 - post_residual as f64 / 30.0); // semi-dead
        }
    }

    // Lookahead: reward if the next item fits into the post residual (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 + 30.0 * snug;
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: slight penalty if gap remains.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: neutral-to-slightly-high default; only chosen when
    // open bins score worse via dead-space/pressure terms.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
    } else {
        // Reward tight fits relative to current residual.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * tightness;
    }

    // Mild preference for bins below mean residual (balancing loads).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    // exact lookahead match: strongly reward leaving exactly next item's size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 ;
    }
    // tight-but-fitting lookahead
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size ;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64) ;
    }
    // penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 + 0.15 * (next_item_size - post_residual) as f64 ;
    }
    // prefer filling bins tightly
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    // pull residuals toward the mean to avoid fragmented odd-sized leftovers
    score -= (mean_residual - post_residual as f64) * 0.3 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    // mild penalty when many bins compete for the same fit: prefer scarcer fits
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 8.0 ;
    }
    // discourage opening a new bin unless the item fits it perfectly well relative to alternatives
    if bin_residual == bin_capacity && item_size < bin_capacity {
        score += 5.0 + 0.1 * (bin_capacity - item_size) as f64 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain (post_residual == next_item_size) is a jackpot.
        if gap == 0.0 {
            score -= 50.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space proportionally.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean residual: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening new bins is costlier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Small bonus for very tight fits (low post residual) generally.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if next_item_size > 0 && post_residual == next_item_size { score -= 60.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size ;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64) ;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { score += 20.0 ; }
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    score -= (mean_residual - post_residual as f64) * 0.3 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    // penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let best_cap = 30.0 + 40.0 * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 10.0)) ;
            score += best_cap * (1.0 - progress) ;
        } else {
            score -= 5.0 ;
        }
    }
    // mild reward for tight fits in crowded state
    if fitting_bins_count > 3 && post_residual > 0 && post_residual < item_size . max (1) * 2 {
        score -= 8.0 ;
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let post = post_residual as f64 ;
    let fill_ratio = 1.0 - post / cap ;
    let next = next_item_size as f64 ;

    // Exact lookahead fit: strong reward
    if next_item_size > 0 && post_residual == next_item_size { score -= 80.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        let norm = slack / cap ;
        score -= 34.0 * (1.0 - norm) * (1.0 - 0.5 * norm) ;
        if slack < 8.0 { score -= 7.0 ; }
        // reward slack that still fits a typical small item
        if slack >= 20.0 && slack < 45.0 { score -= 3.0 ; }
        // extra reward for leaving room for two more small items
        if slack >= 2 * item_size as f64 { score -= 2.0 ; }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 28.0 ;
    }

    // base fill reward
    score -= 18.0 * fill_ratio ;
    score -= (mean_residual - post) * 0.4 ;

    // progress-weighted compaction pressure
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 16.0 * fill_ratio ;

    // scarcity of alternatives
    if fitting_bins_count > 0 {
        score -= 9.0 * (1.0 - 1.0 / fitting_bins_count as f64) * fill_ratio ;
    }

    // dead-space shaping: penalize residuals too small for typical items
    if post > 0.0 && post < 10.0 { score += 7.0 ; }

    // new-bin candidate: penalize more strongly unless open bins are truly bad
    if bin_residual == bin_capacity {
        let waste_estimate = if next_item_size > 0 { (cap - next).max (0.0) } else { 0.0 } ;
        score += 7.0 + 0.08 * waste_estimate - 4.0 * progress ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 18.0 + 0.35 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that remain useful for the lookahead item.
            score -= 8.0 + 0.15 * (post_residual as f64 - next_item_size as f64).min(30.0);
        }
    } else {
        // Last item: only absolute fill matters.
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are globally poor or the item is large relative to mean space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit_quality = mean_residual / bin_capacity as f64;
        let item_pressure = item_size as f64 / bin_capacity as f64;
        // Base penalty so new bins are only chosen when justified.
        score += 45.0;
        // Justify opening when mean residual is low (bins nearly full) or
        // item is large and unlikely to fit elsewhere well.
        score -= 40.0 * (1.0 - mean_fit_quality);
        score -= 25.0 * item_pressure * (0.5 + 0.5 * progress);
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Slight preference for bins below mean residual (balance + preserve large gaps).
    score += 0.10 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild penalty when many bins are open already (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly warped by stream progress.
    // Early on, large residuals are fine (bins stay flexible); later, waste hurts more.
    let progress_warp = 0.5 + 1.5 * progress * progress;
    let mut score = pr * progress_warp;

    // Smooth polynomial coupling of post_residual with progress:
    // penalize mid-size residuals super-linearly as the stream matures.
    let quad = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 40.0 * quad;

    // Perfect-fit reward (smooth, gaussian-like bump near zero post-residual).
    score -= 25.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Lookahead coupling: reward if next item fits the post residual (smooth margin term).
    if next_item_size > 0 {
        let margin = (pr - next_item_size as f64) / cap;
        score -= 18.0 * (margin / (1.0 + margin.abs())).max(0.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild reward when bin is tighter than average (good space utilization).
    score -= 5.0 * ((mean_residual - pr) / cap);

    // Prefer using existing bins over opening new ones, more so early in the stream.
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual relative to capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward very tight fits (small post_residual) but penalize "dead" residuals
    // that are too small to hold any plausible next item.
    if post_residual > 0 && post_residual < 10 {
        // Dead space: nearly unusable. Penalize mildly since it's small.
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Integer-division harmonic classes of post_residual
    let cls = if post_residual == 0 { 0 } else { bin_capacity / post_residual.max(1) };
    match cls {
        1 => score -= 5.0,   // post_residual > 50: roomy, fine
        2 => score += 0.0,   // 25..50: moderately usable
        3..=4 => score += 6.0, // ~12..25: awkward class
        5..=9 => score += 10.0, // ~5..12: poor class
        _ => score += 12.0,  // tiny residual: worst class
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: next item can also go here. Reward proportional to fit quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + slack * 0.05;
        } else {
            // Next item won't fit; penalize if this residual is just barely too small
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: score it mildly high so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
        // Early in stream, slightly more willing to open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Mild preference for filling fuller bins when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: tiny leftover gaps nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual < 15 {
        score += 12.0 * (15.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward placements where the next item fits the residual tightly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
            if slack < 10 {
                score += 8.0;
            }
        } else {
            score += 20.0; // next item won't fit here; residual likely dead
        }
    }

    // Last-chance bonus: only one open bin can fit this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins, stronger early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_penalty = open_bins_count as f64 * (1.0 - progress) * 0.6;
    score += spread_penalty * (1.0 - item_size as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (best-fit flavor), scaled with progress.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Late-stream urgency: fill bins tightly as the stream ends.
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 20.0 * (frac - 0.5);
        } else {
            score += 18.0 * (0.5 - frac);
        }
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (items are 10..80), so punish them hard beyond their raw value.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }

    // Reward exact fits and near-exact fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead space relative to bin capacity: penalize leaving large unusable
    // slack when item is small relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: make the empty bin moderately attractive only when
    // the current bin would leave bad dead space or when few bins fit.
    if bin_residual == bin_capacity {
        score = 55.0
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64) * 0.8
            - (item_size as f64 / bin_capacity as f64) * 20.0;
        // If this placement creates near-zero dead space elsewhere, discourage new bin.
        if post_residual <= 9 && post_residual >= 1 {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item can use the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 12.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be more willing to consolidate; later, tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
