}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step matches: post_residual equal to next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual can still host the next item: mild reward proportional to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space
        score += 15.0;
    }

    // Compare post_residual against mean residual: prefer bins left tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins exist
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Early in the stream, be more willing to open bins / spread load
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny leftovers are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual < 15 {
        score += 12.0 * (15.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead (borrowed from best heuristic): strong reward when the next item
    // exactly fills the residual, graded reward when it fits with small slack.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // next item cannot use this gap
    }

    // Last-chance bonus: only one open bin can fit this item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Spread pressure: mildly discourage opening many bins early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_penalty = open_bins_count as f64 * (1.0 - progress) * 0.6;
    score += spread_penalty * (1.0 - item_size as f64 / bin_capacity as f64);

    // Tightness reward: prefer bins closer to full after placement.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Best-fit flavor relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 20.0 * (frac - 0.5);
        } else {
            score += 18.0 * (0.5 - frac);
        }
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste of the bin's usable space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Leave only tiny unusable slivers -> mild reward.
        score -= 15.0;
    } else if post_residual < 20 {
        // Dead-space zone: small leftovers (10..20) are hard to reuse.
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item cannot fit in the post-residual but this bin could hold
    // a combination, mild penalty for fragmenting.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post_residual as f64 {
            let gap = post_residual as f64 - n;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins
    // would leave large waste or when open bins are plentiful and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins early; relax later in the stream.
        score += 30.0 * (1.0 - progress);
        // Penalize more when few bins are open (opening is wasteful).
        score += 8.0 * (1.0 / (1.0 + open_bins_count as f64));
        // If many fitting bins exist, opening a new bin is rarely good.
        score += 5.0 * (fitting_bins_count as f64).min(10.0);
        // But if the item is large relative to mean residual, existing bins fit poorly.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual + 0.5 * item_size as f64 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the mean (keeps bin states homogeneous),
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with larger residual when item is small
    // (small items are flexible; save tight bins for large items).
    if item_size <= 30 {
        score -= 0.05 * (bin_residual as f64);
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny residuals are nearly unusable.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Fill ratio reward.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: consolidate when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Strong lookahead: exact fit for next item is highly valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // New-bin candidate: attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score = 55.0
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64) * 0.8
            - (item_size as f64 / bin_capacity as f64) * 20.0;
        if post_residual >= 1 && post_residual <= 9 {
            score += 30.0;
        }
        // If next item is large and would waste this fresh bin, discourage.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer tighter bins relative to mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progress-scaled tightness bonus: later in stream, demand tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 4.0 * norm_pr * norm_pr * (0.5 + progress) * cap * 0.1;
    score -= 3.0 * norm_pr * (1.0 - prog3) * (mean_residual / cap);

    // Tight fit reward, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 2.0 * progress) * 5.0;

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= (pr - nxt).min(20.0) * 0.3 * (1.0 - prog2);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating open bins early
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 1.5;

    // New-bin candidate: prefer only when it would be reasonably full later
    if bin_residual == bin_capacity {
        score += 6.0 - 6.0 * progress + 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into residue classes mod 10
    // (capacity fractions). Small residues that are "dead space" get penalized.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // Dead-space penalty: residues 1..9 that cannot combine with typical items
        // are worse than exact fits. Reward class 0 (perfect divisibility).
        score += match class {
            0 => -6.0,
            1 | 2 | 3 | 4 => 4.0 + class as f64,      // unusable slivers
            5 | 6 | 7 | 8 | 9 => 1.5,                  // marginally usable
            _ => 0.0,
        };
    } else {
        score -= 10.0; // perfect fit
    }

    // Integer-division thresholds on post_residual vs next_item_size:
    // does the lookahead item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainability reward, stronger if next item also lands on class 0
            let chain_bonus = if (pr - next_item_size) % 10 == 0 { 8.0 } else { 5.0 };
            score -= chain_bonus;
        } else {
            // post residual cannot host next item -> dead end risk
            score += 3.0 + (next_item_size - pr) as f64 * 0.05;
        }
        // Harmonic pairing: next_item_size and post_residual share gcd-like class
        let g = gcd(pr, next_item_size);
        if g >= 10 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // New-bin candidate logic: empty bin gets a baseline penalty so we prefer
    // reusing open bins unless the fit is terrible.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if existing bins would leave very small dead space, opening fresh
        // is fine; if mean residual is large, reuse is attractive.
        if mean_residual > 30.0 {
            score += 6.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Coupling: penalize leaving residual just below common item sizes (10..80)
    for k in 1..=8u32 {
        let t = k * 10;
        if pr >= t && pr < t + 5 {
            score += 1.0; // near-miss of a harmonic threshold
        }
    }

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are nearly unusable
    // by future items (min item size 1..100 unknown, but small gaps waste space).
    let dead = post_residual as f64;
    if post_residual >= 1 && post_residual <= 12 {
        score += 40.0 - 3.0 * dead; // small gaps are worst
    } else if post_residual > 60 {
        score -= 6.0; // large leftover stays flexible
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid fragmenting further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.8 * pressure * (1.0 - tightness);

    // Mean residual coupling: if this bin is far below mean residual, it's
    // already crowded — prefer it; if far above, opening elsewhere is fine.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: default is acceptable, but penalize when
    // decent fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // If lookahead item won't fit a fresh residual anyway, discourage new bin.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 5.0;
        }
    } else {
        // Lookahead synergy: if next item exactly fills the post-residual, big reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    // exact-match lookahead bonus (strongly reward leaving room exactly for next item)
    if next_item_size > 0 && post_residual == next_item_size { score -= 70.0 ; }
    // tight-but-feasible lookahead: reward small slack after placing next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size ;
        score -= 28.0 * (1.0 - slack as f64 / bin_capacity as f64) ;
    }
    // dead space penalty: residual that next item cannot use is wasted
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = post_residual as f64 / next_item_size as f64 ;
        score += 18.0 + 15.0 * waste_ratio ;
    }
    // compactness reward: prefer fuller bins
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    // global residual pressure
    score -= (mean_residual - post_residual as f64) * 0.3 ;
    // late-stream urgency: pack tightly as stream progresses
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    // scarcity coupling: when few bins fit the item, favor the best-fitting open bin
    if fitting_bins_count >= 2 {
        score -= (fitting_bins_count . min (6) as f64) * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    } else if fitting_bins_count == 1 {
        score -= 8.0 ;
    }
    // new-bin candidate: penalize opening a fresh bin unless the current stream
    // is early or the item would leave a very poor residual in every open bin
    if bin_residual == bin_capacity && post_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64 ;
        score += 30.0 - 20.0 * item_ratio + 15.0 * progress ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this bin a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: place here, next item closes bin exactly.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: good chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: dead space penalty grows with gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // --- Tightness reward relative to current residual ---
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // --- Penalize unusable slivers (dead space below min item size) ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    // --- Last-chance bin: strongly reward using the only fitting bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // --- New bin candidate handling ---
    if is_new_bin {
        // Opening a new bin is penalized mildly; it should win only when
        // all existing fits are poor (high post_residual elsewhere).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 20.0 * progress;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 10.0;
        }
    } else if fitting_bins_count > 1 {
        // Slight preference to consolidate into fewer bins when alternatives exist.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let post = post_residual as f64 ;
    let fill_ratio = 1.0 - post / cap ;
    let next = next_item_size as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;

    // Exact lookahead fit: strong reward
    if next_item_size > 0 && post_residual == next_item_size { score -= 80.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        let norm = slack / cap ;
        score -= 34.0 * (1.0 - norm) * (1.0 - 0.5 * norm) ;
        if slack < 6.0 { score -= 7.0 ; }
        // reward slack that still fits a typical small item
        if slack >= 20.0 && slack < 45.0 { score -= 3.0 ; }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 28.0 ;
    }

    // base fill reward
    score -= 18.0 * fill_ratio ;
    score -= (mean_residual - post) * 0.35 ;

    // progress-weighted compaction pressure
    score -= progress * 16.0 * fill_ratio ;

    // scarcity of alternatives
    if fitting_bins_count > 0 {
        score -= 9.0 * (1.0 - 1.0 / fitting_bins_count as f64) * fill_ratio ;
    }

    // dead-space shaping: penalize residuals too small for typical items
    if post > 0.0 && post < 10.0 { score += 6.5 ; }
    if post > 0.0 && post < 5.0 { score += 4.0 ; }

    // new-bin candidate: penalize more strongly unless open bins are truly bad
    if bin_residual == bin_capacity {
        let waste_estimate = if next_item_size > 0 { (cap - next).max (0.0) } else { 0.0 } ;
        score += 7.0 + 0.08 * waste_estimate - 4.0 * progress ;
        // late in the stream, prefer consolidating into open bins
        if progress > 0.8 { score += 3.0 ; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits perfectly into post_residual, strongly favor
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize wasting large residuals
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is large or fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 - bin_capacity as f64).abs();
        let bias = 15.0 + 30.0 * (1.0 - progress) + 0.2 * mean_residual;
        // open new bin if item is huge (would leave big dead space elsewhere) or fits nothing well
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.7 || (fitting_bins_count <= 1 && mean_residual < item_size as f64) {
            score -= bias;
        } else {
            score += bias;
        }
    }

    // Mild preference to fill bins with larger residuals when many bins are open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let cap = bin_capacity as f64;

