    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // --- Mean residual coupling ---
    score += 0.3 * (mean_residual - post_residual as f64);

    // --- Progress-weighted fill pressure (borrowed from best heuristic) ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap);

    // --- Last-chance bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // --- New bin candidate handling ---
    if is_new_bin {
        score += 35.0 + 20.0 * progress;
        if next_item_size > 60 {
            score -= 10.0;
        }
    } else if fitting_bins_count > 1 {
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), non-linearly
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Stream-progress coupling: late in the stream, tighten more aggressively
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual of open bins
    score += 0.35 * (pr as f64 - mean_residual).abs();

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - nx / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: keep it as a neutral fallback with slight late-stream penalty
    if bin_residual == bin_capacity {
        score = cap * (1.05 - 0.25 * progress) + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
