pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets of 10 (capacity fractions)
    let post_class = post_residual / 10;
    let post_mod = post_residual % 10;

    // Reward placing into bins whose post-residual falls into "useful" classes
    // (residuals that future items 10..80 can still fill well).
    match post_class {
        0 => score -= 40.0,          // near-perfect fill
        1 => score -= 30.0,          // 10..19: fits smallest items
        2 => score -= 22.0,          // 20..29
        3 => score -= 16.0,
        4 => score -= 12.0,
        5 => score -= 9.0,
        6 => score -= 6.0,
        7 => score -= 3.0,
        8 => score -= 1.0,
        _ => {}                      // 90+: essentially empty bin
    }

    // Penalize awkward remainders (dead space that nothing can use)
    if post_mod > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic coupling with lookahead item: does next_item fit the post_residual class?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // next item fits exactly-ish: strong reward for leaving a compatible class
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 18.0;
            } else {
                score -= (gap as f64) * 0.15;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += ((next_item_size as u32 - post_residual) as f64) * 0.35;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, but allow it when residual waste would be large
    if bin_residual == bin_capacity {
        let waste_if_existing = mean_residual - item_size as f64;
        let mut nb = 20.0;
        if waste_if_existing > 40.0 {
            nb -= (waste_if_existing - 40.0) * 0.5;
        }
        // late in the stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 15.0;
        score += nb;
    }

    // Prefer fuller bins relative to mean residual (tight packing)
    score += ((mean_residual - bin_residual as f64).max(-50.0).min(50.0)) * 0.1;

    // Modulo-20 harmonic class of bin_residual: bins aligned to common item sizes
    let res_mod = bin_residual % 20;
    if res_mod == 0 {
        score -= 4.0;
    } else if res_mod >= 17 {
        score += 3.0; // awkward 17..19 leftover band
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 65.0 ;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size ;
        score -= 28.0 * (1.0 - slack as f64 / bin_capacity as f64) ;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 22.0 ;
    }
    // tight fit bonus for the current item
    if post_residual > 0 && item_size > 0 && post_residual + item_size <= bin_capacity {
        let fill = item_size as f64 / (post_residual as f64) ;
        if fill > 0.8 { score -= 12.0 * (fill - 0.8) ; }
    }
    // penalize opening a new bin when open bins can fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 30.0 + 5.0 * (fitting_bins_count as f64).ln() ;
    }
    // reward new bin only late in stream when open bins are fragmented
    if bin_residual == bin_capacity && fitting_bins_count == 0 {
        let progress = step_index as f64 / total_items . max (1) as f64 ;
        score -= 8.0 * progress ;
    }
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    score -= (mean_residual - post_residual as f64) * 0.33 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64) ;
    // slight preference for bins with residual divisible-friendly to next item
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual % next_item_size ;
        if rem == 0 { score -= 10.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..10)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 4.0;
    }
    // Gaps too small for the next item are likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Perfect fit: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * (1.0 - progress));

    // New-bin candidate: make it moderately attractive only when the fit here
    // would be poor (large post residual) or dead space would result.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        if post_residual >= 10 && post_residual as f64 >= mean_residual {
            score -= 10.0;
        }
    }

    // Slight preference for bins with below-average residual (more packed bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let post = post_residual as f64 ;
    let fill_ratio = 1.0 - post / cap ;
    let next = next_item_size as f64 ;

    // Exact lookahead fit: strong reward
    if next_item_size > 0 && post_residual == next_item_size { score -= 80.0 ; }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        let norm = slack / cap ;
        score -= 34.0 * (1.0 - norm) * (1.0 - 0.5 * norm) ;
        if slack < 8.0 { score -= 7.0 ; }
        // reward slack that still fits a typical small item
        if slack >= 20.0 && slack < 45.0 { score -= 3.0 ; }
        // penalize slack that is awkwardly between typical sizes
        if slack >= 8.0 && slack < 20.0 { score += 2.0 ; }
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 28.0 ;
    }

    // base fill reward
    score -= 18.0 * fill_ratio ;
    score -= (mean_residual - post) * 0.38 ;

    // progress-weighted compaction pressure
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    score -= progress * 17.0 * fill_ratio ;

    // scarcity of alternatives
    if fitting_bins_count > 0 {
        score -= 9.0 * (1.0 - 1.0 / fitting_bins_count as f64) * fill_ratio ;
    }

    // dead-space shaping: penalize residuals too small for typical items
    if post > 0.0 && post < 10.0 { score += 7.0 ; }

    // new-bin candidate: penalize more strongly unless open bins are truly bad
    if bin_residual == bin_capacity {
        let waste_estimate = if next_item_size > 0 { (cap - next).max (0.0) } else { 0.0 } ;
        score += 7.0 + 0.08 * waste_estimate - 4.0 * progress ;
        // late in the stream, opening new bins is rarely worth it
        if progress > 0.8 { score += 3.0 ; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Slack between post_residual and next item; smaller slack = better.
            let slack = pr - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Perfect fill next step: strong reward.
            if slack == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here; post_residual becomes dead space.
            score += 0.5 * (nxt - pr);
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful bin).
    let cap = bin_capacity as f64;
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize tiny dead space (< smallest item) that becomes unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Late in stream: favor tight fits to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.2;

    // Prefer keeping new-bin candidate slightly discouraged unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

