pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: exact fit for next item is highly valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Dead-space avoidance: tiny residuals are nearly unusable.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }

    // Reward exact and near-exact fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Fill ratio reward.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Tightness reward relative to capacity.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bins pressure: consolidate when many bins are open.
    score += (open_bins_count as f64) * 1.2;

    // Mean residual coupling.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progress-scaled tightness bonus.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let best_possible = if fitting_bins_count > 0 {
            // Estimate quality of best existing fit: penalize opening new bins more
            // when several bins can already fit the item.
            30.0 + (fitting_bins_count as f64) * 8.0
        } else {
            5.0
        };
        score = 55.0 + best_possible
            - (item_size as f64 / bin_capacity as f64) * 20.0
            - (open_bins_count as f64) * 0.5;
        // Late in stream, prefer consolidating into open bins.
        score += progress * 15.0;
        // If next item is large, a fresh bin preserves room — mild bonus.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Penalize unusable dead space: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 + 20.0 * chain_fit;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap that blocks the known next item
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless item is large
    // or no good open-bin option exists (high mean residual fragmentation).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // New bin attractive for big items late in stream or when open bins are fragmented
        let fragmentation = (mean_residual - bin_residual as f64).abs() / bin_capacity as f64;
        let openness = 0.5 * fill_ratio + 0.3 * progress + 0.4 * fragmentation;
        if openness > 0.55 {
            score -= 10.0 * (openness - 0.55);
        } else {
            score += 60.0 * (0.55 - openness);
        }
        // Never open a new bin when several bins fit and item is small
        if fitting_bins_count > 2 && fill_ratio < 0.4 {
            score += 80.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit style)
        let slack = (bin_residual - item_size) as f64;
        score += 0.15 * slack;

        // Reward reducing dispersion: placing into a bin far below mean residual
        if (bin_residual as f64) < mean_residual {
            score -= 0.25 * (mean_residual - bin_residual as f64);
        }
    }

    // Time horizon: early on, keep bins flexible (favor moderate post_residual);
    // late in stream, be greedy for tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 15.0 * tight;
    } else if progress < 0.2 && post_residual as f64 > 0.6 * bin_capacity as f64 {
        score -= 5.0; // keep large flexible bins around early
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
