    // capacity-fraction buckets. Leftovers in the lowest class (tiny scraps)
    // are nearly dead space -> penalize heavily.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class index via integer division thresholds: 0..=12 (post/8 buckets)
    let class = post_residual / 8;
