        1 => score += 30.0,                 // 8-15
        2 => score += 15.0,                 // 16-23
        3 => score += 6.0,                  // 24-31
        4 => score += 0.0,                  // 32-39: usable for small items
        5 => score -= 2.0,
        6 => score -= 5.0,                  // 48-55: fits typical mid items
        7 => score -= 8.0,
        8 => score -= 10.0,                 // 64-71: sweet spot
        9 => score -= 8.0,
        10 => score -= 5.0,
        11 => score -= 2.0,
        _ => {}                             // >=96: near-empty bin, neutral
    }

    // Modulo-10 harmony: leftover that is a multiple of 10 pairs well with
    // the 10..80 item granularity; odd scraps are harder to fill.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: reward if next item fits exactly / harmonically
    // into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;                  // perfect pairing
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 12.0;              // near-perfect pairing
            } else {
                score -= (10.0 * gap as f64) / cap.min(60.0);
            }
        } else {
            // next item cannot fit here: leftover must survive another round
            score += 6.0 + (post_residual % 17) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has huge raw residual; make it
    // attractive only when existing bins are badly fragmented or the item
    // fits nothing well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap - 0.5).abs();
        // Prefer new bin early, or when open bins are fragmented / scarce fits
        score = cap * 0.55
            - 18.0 * (1.0 - progress)
            - 25.0 * fragmentation
