    // Mild penalty for wasting a very large bin residual on a tiny item.
    if item_size < 20 && bin_residual > 70 && bin_residual < bin_capacity {
        score += 8.0;
    }

    // Slight preference to keep many bins' residuals near the harmonic mean.
    score += ((post - mean_residual) / cap).abs() * 3.0;

    score
}

