    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 35.0;
        // but if stream is early or many bins are open, new bins are cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
