            score += 12.0; // next item won't fit here; dead space likely
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tight fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    if bin_residual < bin_capacity {
        score += pressure * 0.3;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless it's a poor fit situation.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin if current bin would leave large dead space anyway.
        if post_residual > 40 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still fit the next item: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to lookahead: penalize unusable gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize leaving tiny unusable slivers (< smallest item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Slight preference for keeping many open bins consolidated early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New empty bin: only attractive if nothing fits well (high post-fit waste elsewhere).
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host current + next item pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly prefer filling bins tightly: reward small post_residual non-linearly
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight_fit * tight_fit;

    // Perfect fit gets an extra big reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Penalize creating dead space that no future item (min size 1..10 typical) could use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasteful unless it's a near-perfect fit
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress; // increasingly important late in the stream
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // chain fit: this placement sets up a perfect next placement
        } else if post_residual >= next_item_size {
            score -= 5.0; // next item still fits here
        } else {
            // next item won't fit: penalize slightly, but less if post_residual is small anyway
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // New-bin candidate handling: opening a new bin wastes capacity of all open bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 30.0;
        // More open bins => more waste if we abandon them; penalize more
        score += 2.0 * open_bins_count as f64;
        // If other bins can fit the item, discourage new bin strongly
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them)
        score -= 25.0 * (1.0 - progress);
        // If mean residual across open bins is small (bins nearly full), a new bin is fine
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        // Large items leave big residuals; if item is large, new bin may be good
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    } else {
        // Slight preference for using bins with smaller residuals (best-fit bias)
        score += (bin_residual as f64 - post_residual as f64) * 0.05;
