        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Global pressure: many open bins -> encourage consolidating into existing bins
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 3.0 * open_bins_count as f64 * 0.1;
    }

    // Mild time-horizon modulation: late in stream, prioritize finishing bins tightly
    if progress > 0.8 {
        score += post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear shaping of post-residual.
    let mut score = pr
        + 40.0 * pr_norm * pr_norm * (1.0 - pr_norm)
        - 25.0 * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Stream-progress coupling: as stream advances, tolerate residual less
    // (push toward filling bins), smoothly via polynomial in progress.
    let urgency = progress * progress * (3.0 - 2.0 * progress);
    score -= urgency * (1.0 - pr_norm) * 30.0;
    score += urgency * pr_norm * pr_norm * 20.0;

    // Dead-space penalty relative to mean residual (smooth coupling).
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin bonus: strongly favor using it before opening new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        score -= 6.0 * (fitting_bins_count.min(6) as f64) / 6.0;
    }

    // Lookahead: reward if next item can fit into post_residual.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 18.0 * (next_item_size as f64 / cap);
        } else {
            score += 10.0 * (1.0 - (next_item_size as f64 / cap));
        }
    }

    // Slight penalty for spreading across many open bins early on.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.4;

    // New-bin candidate: penalize mildly unless existing options are poor.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * urgency;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: coarse quantization of post_residual
    // into capacity fractions (dead-space classes).
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor(); // 0..10 harmonic class
