    // Perfect fit: strongly reward zero / tiny post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Lookahead: reward if the next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let nxt_frac = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * (1.0 - nxt_frac);
        } else {
            // next item cannot follow here: penalize leaving medium gaps
            score += 40.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity or current bins are quite full on average.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // open new bin only for big items or when open bins are nearly full
        if item_frac < 0.5 && mean_frac < 0.75 {
            score += 500.0;
        } else {
            score += 50.0;
        }
    }

    // Modulo-arithmetic harmonic bonus: residuals that are multiples of common
    // small item sizes (10, 20, 25) are more reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 30.0;
    }

    // Penalize creating unusable dead space: residual smaller than min item (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Mild preference to fill existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Prefer bins whose residual is close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.5;

    score
}

