    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item can't use the leftover gap
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when it leaves a large,
