    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual < 30 {
            score += 35.0; // opening a bin for a near-full fill wastes it
        }
    }

    // Deviation from mean residual: prefer bins that are already tight.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 8.0;

    score
}

