pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual).
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Harmonic class penalty: dead space in "unusable" residue classes is worse.
    // Residuals that are too small for the smallest plausible item (<= 10) are dead.
    if post_residual < 10 {
        score += 25.0;
    } else {
        // Classify post_residual by harmonic bucket (mod 10): some classes are
        // more reusable given the lookahead item.
        let class = post_residual % 10;
        let class_bonus = match class {
            0 => 8.0,            // round residual: easy to fill exactly later
            5 => 5.0,            // half-decade residual
            _ => 0.0,
        };
        score -= class_bonus as f64;

        // Exact-fill classes relative to next item: post_residual == next_item_size
        // means next item perfectly fills this bin -> huge reward.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 30.0;
            } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
                // next item nearly fills bin: good chaining
                score -= 12.0;
            } else if next_item_size > post_residual && post_residual > 0 {
                // next item cannot use this bin's residual: mild penalty,
                // unless residual is tiny (already counted) or large (flexible)
                let flexibility = (post_residual as f64 / bin_capacity as f64).sqrt();
                score += 6.0 * (1.0 - flexibility);
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: empty bin should only win when all open bins
    // would leave bad residue. Penalize opening a new bin generally.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0
            + 15.0 * (1.0 - progress)          // early stream: prefer consolidating
            + 0.5 * open_bins_count as f64;    // too many open bins already
        // But if mean residual across open bins is small (all bins tight),
        // opening a fresh bin is reasonable.
        score -= 25.0 * (1.0 - (mean_residual / bin_capacity as f64)).powi(2);
    }

    // Mild preference to spread load when many bins are open and this bin is large.
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized
    // relative to their size, since they can never host an item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item likely can't use this gap
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
