    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 20.0;
        // open a new bin if the item would leave awkward space in every open bin
        if post_residual > 0 && post_residual < 10 && fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Late-stream tightening: waste matters more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

