pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by coarse residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic fraction classes of post_residual relative to capacity.
    // Leftovers near capacity/n (n=2,3,4) are reusable by common item sizes.
    let frac = pr / cap;
    let harmonic_bonus = if frac > 0.0 {
        let mut best = 0.0f64;
        for (n, w) in [(2.0, 30.0), (3.0, 20.0), (4.0, 12.0), (5.0, 6.0)] {
            let d = (frac - 1.0 / n).abs();
            if d < 0.08 {
                let b = w * (1.0 - d / 0.08);
                if b > best { best = b; }
            }
        }
        best
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead space penalty: small unusable leftovers (0 < post < 10 typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 40.0;
        } else {
            // next item cannot fit here: penalize proportionally to waste
            score += (next_item_size as f64 - pr).min(60.0) * 0.5;
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Modulo-class coupling: reward when post_residual and next_item_size share a residue class.
    if next_item_size > 0 && post_residual > 0 {
        let r = post_residual % 10;
        let rn = next_item_size % 10;
        if r == rn && post_residual >= next_item_size {
            score -= 15.0;
        }
        // Integer-division threshold: leftovers divisible into halves of next item.
        if next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 10.0;
        }
    }

    // Mild pressure to keep open bin count low late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * progress * 0.3;

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - pr) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual is "dead" if it is too small to hold even the smallest plausible item.
    let dead_threshold = 8.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large waste when the gap can't fit the lookahead item either.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += (next_item_size - post_residual as u32) as f64 * 0.5;
    }
    // Reward when the lookahead item fits into the post-residual.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make the empty bin slightly unattractive unless the item
    // is huge relative to typical residuals or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
    }

    // Slight preference for bins below mean residual (tighter bins get used first).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between the
    // post-placement residual and the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: large subtraction so this bin wins.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatches proportionally, more for larger next items.
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            score += diff * (0.5 + 1.5 * next_frac);
            // Bonus if next item still fits after this placement (pairing viable).
            if post_residual >= next_item_size {
                score -= 4.0 + 6.0 * next_frac;
            }
        }
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins that keep residuals near the mean (balanced packing),
    // penalize outliers that create unusable dead space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize tiny dead space (< 10) which is hard to fill later,
    // but only if it doesn't match the next item.
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && post_residual == next_item_size) {
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): penalize moderately so we prefer reusing
    // existing bins with decent fits, but allow opening when fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If lookahead pairs perfectly with a fresh bin, still allow it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 25.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
    }

    // Prefer fuller bins overall (small post_residual already does this,
    // add slight extra tilt).
    score += 0.05 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Slack left for next item; reward proportional to how well it matches.
            let slack = post - next;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 30.0; // perfect pairing bonus
            }
        } else {
            // Next item won't fit here; slightly penalize leaving a gap nothing can use.
            score += 5.0 * (1.0 - post / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * (1.0 - progress);
        // But if mean residual across open bins is too small for the item, new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // If next item is large, prefer a fresh bin to keep room.
        if next_item_size >= item_size && next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Favor bins whose residual is close to mean (balanced usage) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Late in the stream, consolidate: prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

