pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in [0,1]
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Non-linear polynomial coupling of fit quality with progress.
    // Tight fits (small post_residual) get progressively more rewarded.
    let cap_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap_f); // 0 = loose, 1 = exact fit
