    score -= 18.0 * poly;

    // Perfect-fit bonus, smoothly scaled by progress
    if post_residual == 0 {
        score -= 12.0 * (1.0 + progress);
    }

    // Penalize dead space that is too small for any plausible item
    // (smooth: penalty grows as post_residual shrinks below a soft threshold)
    if post_residual > 0 {
        let dead = (10.0_f64 - post_residual as f64).max(0.0) / 10.0;
        score += 10.0 * dead * dead;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0 * (1.0 - post_residual as f64 / cap_f);
        } else {
            // penalize leaving a gap that next item cannot use
            let gap = (next_item_size as f64 - post_residual as f64) / cap_f;
            score += 6.0 * gap * gap;
        }
    }

    // New-bin candidate: mildly discourage when decent open options exist,
    // encourage when residual space is fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - post_residual as f64).abs() / cap_f
        } else {
            1.0
        };
        score += 5.0 * (1.0 - fragmentation * fragmentation);
        // late in stream, opening new bins wastes capacity
        score += 10.0 * progress;
    }

    // Mild penalty for leaving large residuals when many bins are open
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the dead space: residues divisible by small moduli
    // are more likely to be filled by future items (sizes 1..100).
    let pr = post_residual;
    if pr > 0 {
        // Penalize "odd" dead space classes more; reward round classes.
        let class_penalty: f64 = if pr % 10 == 0 {
            -4.0
        } else if pr % 5 == 0 {
            -2.0
        } else if pr % 2 == 0 {
            0.0
        } else {
