                10.0
            } else if pr2 % 5 == 0 {
                6.0
            } else {
                3.0
            };
            score -= chain;
        } else {
            // Next item cannot use this bin's remainder: mild penalty,
            // worse the larger the unusable gap.
            score += (next_item_size - pr).min(20) as f64 * 0.5;
        }
    }

