    // using it over opening a new bin (unless post residual would be tiny).
    if fitting_bins_count == 1 {
        if pr >= 10 {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual, so its
    // raw score is high. Adjust based on how fragmented the open bins are.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Open new bins more readily early on / when existing residuals are tight.
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
