    } else {
        // Mild preference for tighter existing bins (smaller residual chosen first).
        score += (bin_residual as f64) * 0.05;
        // Prefer bins below mean residual slightly (pack tight bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Cap open-bin sprawl: with many open bins, discourage opening more.
    if open_bins_count > 8 && bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

